// Real optimized Wasm, direct + Worker. Fixtures are generated by icc_groups.rs.
import assert from 'node:assert/strict';
import {chromium} from 'playwright-core';
import {createServer} from 'node:http';
import {readFile, mkdir, writeFile} from 'node:fs/promises';
import {resolve, extname, sep} from 'node:path';
import {fileURLToPath} from 'node:url';
import {createHash} from 'node:crypto';

const repo = fileURLToPath(new URL('../../', import.meta.url));
const web = resolve(repo, 'web');
const fixtures = resolve(process.env.RZPDF_ICC_FIXTURES ?? resolve(repo, 'output/webassembly/icc-fixtures'));
const out = resolve(repo, 'output/webassembly/icc-browser');
await mkdir(out, {recursive: true});
const names = ['linear-group.pdf', 'unsupported-group.pdf', 'many-profiles.pdf', 'sparse-cid.pdf', 'cyclic-color.pdf', 'type3-rectangles.pdf'];
const server = createServer(async (req, res) => {
  try {
    const path = decodeURIComponent(new URL(req.url, 'http://localhost').pathname);
    const file = names.some(name => path === '/' + name)
      ? resolve(fixtures, path.slice(1)) : resolve(web, '.' + (path === '/' ? '/index.html' : path));
    if (!file.startsWith(web + sep) && !names.some(name => file === resolve(fixtures, name))) {
      res.writeHead(403).end(); return;
    }
    res.setHeader('Content-Type', ({'.js': 'text/javascript', '.mjs': 'text/javascript', '.wasm': 'application/wasm', '.html': 'text/html'})[extname(file)] ?? 'application/octet-stream');
    res.end(await readFile(file));
  } catch { res.writeHead(404).end(); }
});
await new Promise(done => server.listen(0, '127.0.0.1', done));
const report = {status: 'failed', checks: [], errors: [], artifacts: {}, fixtures: {}};
let browser;
try {
  for (const name of ['rzpdf_web.wasm', 'rzpdf_web.mjs', 'client.js', 'worker-client.js', 'pdf-worker.js']) {
    report.artifacts[name] = createHash('sha256').update(await readFile(resolve(web, 'dist', name))).digest('hex');
  }
  for (const name of names) report.fixtures[name] = createHash('sha256').update(await readFile(resolve(fixtures, name))).digest('hex');
  report.driverSha256 = createHash('sha256').update(await readFile(fileURLToPath(import.meta.url))).digest('hex');
  browser = await chromium.launch({executablePath: process.env.RZPDF_CHROMIUM, headless: true});
  report.browser = await browser.version();
  const page = await browser.newPage();
  page.on('pageerror', error => report.errors.push(error.message));
  await page.goto(`http://127.0.0.1:${server.address().port}`);
  report.checks = await page.evaluate(async () => {
    const {createEngine} = await import('/dist/client.js');
    const {createWorkerEngine} = await import('/dist/worker-client.js');
    const checks = [], check = (value, message) => { if (!value) throw Error(message); };
    const bytes = async name => new Uint8Array(await (await fetch('/' + name)).arrayBuffer());
    for (const worker of [false, true]) {
      const engine = await (worker ? createWorkerEngine() : createEngine());
      try {
        check((await engine.capabilities()).maxIccTransformEstimatedBytes === 33554432, 'observable module ICC table budget');
        const linear = await engine.open(await bytes('linear-group.pdf'));
        const image = await linear.render(0, 72, {annotations: false, includeWidgets: false});
        const pixel = Array.from(image.pixels.slice((10 * image.width + 10) * 4, (10 * image.width + 10) * 4 + 4));
        check(pixel.slice(0, 3).every(v => Math.abs(v - 188) <= 3) && pixel[3] === 255, `linear-light mixing oracle: ${pixel}`);
        await linear.close();
        const cff = await engine.open(await bytes('sparse-cid.pdf'));
        const glyph = await cff.render(0, 72);
        const glyphInk = glyph.pixels.filter((v, i) => i % 4 === 0 && v < 128).length;
        check(glyphInk > 50, `sparse CFF CID 42/GID 2 must paint, ink=${glyphInk}`);
        await cff.close();
        const cyclic = await engine.open(await bytes('cyclic-color.pdf'));
        for (let retry = 0; retry < 2; retry++) {
          let error;
          try { await cyclic.render(0, 36); } catch (e) { error = e; }
          check(error?.code === 'resource_limit', 'cyclic colour reference fails without trapping');
          await cyclic.state();
          const recovery = await cyclic.render(1, 36);
          check(recovery.pixels.some((v, i) => i % 4 !== 3 && v < 10), 'render after colour-cycle failure');
        }
        await cyclic.close();
        const type3 = await engine.open(await bytes('type3-rectangles.pdf'));
        let canonical;
        for (const pageIndex of [0, 1]) {
          const preflight = await type3.fontRequirements(pageIndex);
          check(preflight.complete && preflight.fonts.length === 0, 'Type3 glyphs need no external font');
          const text = await type3.extractText(pageIndex);
          check(text.characters.map(c => c.unicode ?? '').join('') === 'A', 'Type3 reflected text extraction');
          const image = await type3.render(pageIndex, 72);
          check(image.pixels.filter((v, i) => i % 4 === 0 && v < 128).length > 100, 'Type3 glyph must paint');
          if (canonical) check(image.pixels.length === canonical.length && image.pixels.every((v, i) => v === canonical[i]), 'FontBBox corner order must not change glyph pixels');
          else canonical = image.pixels.slice();
        }
        check((await type3.extractText(2)).characters.length === 1024, 'dense Type3 character count');
        for (const dpi of [72, 144]) {
          const dense = await type3.render(2, dpi);
          check(dense.pixels.filter((v, i) => i % 4 === 0 && v < 128).length > 1024, 'dense Type3 curves fit unchanged browser work budget');
          const region = {x: 40, y: 20, width: 32, height: 48};
          const tile = await type3.renderRegion(2, region, dpi);
          for (let row = 0; row < region.height; row++) {
            const start = ((region.y + row) * dense.width + region.x) * 4;
            check(tile.pixels.slice(row * region.width * 4, (row + 1) * region.width * 4).every((v, i) => v === dense.pixels[start + i]), 'trimmed coverage keeps Type3 tile seams identical');
          }
        }
        await type3.close();
        const unsupported = await engine.open(await bytes('unsupported-group.pdf'));
        for (let retry = 0; retry < 2; retry++) {
          let error;
          try { await unsupported.render(0, 36); } catch (e) { error = e; }
          check(error?.code === 'unsupported', `unsupported space is a normal error: ${error?.code}`);
          const text = await unsupported.extractText(0);
          check(text.characters.map(c => c.unicode ?? '').join('') === 'ABC', 'text survives unsupported group blending space');
          await unsupported.state();
        }
        await unsupported.close();
        const many = await engine.open(await bytes('many-profiles.pdf'));
        const failures = [];
        for (let retry = 0; retry < 2; retry++) {
          let error;
          try { await many.render(0, 36); } catch (e) { error = e; }
          check(error?.code === 'resource_limit' && error.resource?.reason === 'icc_transform_bytes', `bounded tables return resource metadata: ${error?.message}`);
          check(error.resource.stage === 'color_conversion' && error.resource.limit === 33554432 && error.resource.actual > error.resource.limit, 'typed limit/actual');
          failures.push(error.resource);
          await many.state(); await many.extractText(0); await many.clearRenderCaches();
          const recovery = await many.render(1, 36);
          check(recovery.pixels.some((v, i) => i % 4 !== 3 && v < 10), 'lighter page renders after rejection');
        }
        await many.close();
        check((await engine.statistics()).handles === 0, 'all handles released');
        checks.push({transport: worker ? 'worker' : 'sync', pixel, failures, glyphInk, colourCycleRecovery: true, type3RectangleEquivalence: true, textIndependent: true, recovery: true});
      } finally { engine.dispose(); }
    }
    return checks;
  });
  assert.equal(report.checks.length, 2);
  assert.equal(report.errors.length, 0);
  report.status = 'passed';
} catch (error) { report.errors.push(error.stack); process.exitCode = 1; }
finally {
  await browser?.close(); await new Promise(done => server.close(done));
  await writeFile(resolve(out, 'report.json'), JSON.stringify(report, null, 2));
  console.log(JSON.stringify(report, null, 2));
}
